import * as d3 from 'd3';
import { navigateTo } from '../state';

export type Sel = d3.Selection<SVGGElement, unknown, null, undefined>;

export interface LabelOpts {
  size?: number;
  weight?: string;
  color?: string;
  anchor?: 'start' | 'middle' | 'end';
  font?: string;
}

export function drawLabel(
  g: Sel,
  x: number,
  y: number,
  text: string,
  opts: LabelOpts = {}
): void {
  const {
    size = 12,
    weight = '400',
    color = 'var(--text)',
    anchor = 'middle',
    font = 'system-ui, -apple-system, BlinkMacSystemFont, sans-serif'
  } = opts;

  g.append('text')
    .attr('x', x)
    .attr('y', y)
    .attr('text-anchor', anchor)
    .attr('dominant-baseline', 'middle')
    .attr('fill', color)
    .attr('font-size', `${size}px`)
    .attr('font-weight', weight)
    .attr('font-family', font)
    .text(text);
}

export interface ArrowOpts {
  color?: string;
  dashed?: boolean;
  label?: string;
  labelSide?: 'left' | 'right' | 'top';
}

export function drawArrow(
  g: Sel,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  opts: ArrowOpts = {}
): void {
  const { color = '#78909c', dashed = false, label, labelSide = 'right' } = opts;

  const arrowId = `arrow-${Math.random().toString(36).slice(2, 9)}`;
  const defs = g.selectAll('defs').data([null]).join('defs');
  defs
    .append('marker')
    .attr('id', arrowId)
    .attr('viewBox', '0 -5 10 10')
    .attr('refX', 10)
    .attr('refY', 0)
    .attr('markerWidth', 8)
    .attr('markerHeight', 8)
    .attr('orient', 'auto')
    .append('path')
    .attr('d', 'M0,-5L10,0L0,5')
    .attr('fill', color);

  g.append('path')
    .attr('d', `M${x1},${y1} L${x2},${y2}`)
    .attr('fill', 'none')
    .attr('stroke', color)
    .attr('stroke-width', 1.5)
    .attr('stroke-dasharray', dashed ? '5,3' : 'none')
    .attr('marker-end', `url(#${arrowId})`);

  if (label) {
    const mx = (x1 + x2) / 2;
    const my = (y1 + y2) / 2;
    let lx = mx;
    let ly = my;
    let anchor: 'start' | 'middle' | 'end' = 'middle';
    if (labelSide === 'left') {
      lx = mx - 8;
      anchor = 'end';
    } else if (labelSide === 'right') {
      lx = mx + 8;
      anchor = 'start';
    } else if (labelSide === 'top') {
      ly = my - 8;
    }
    drawLabel(g, lx, ly, label, { size: 9, color: '#666', anchor });
  }
}

export interface MatrixBlockOpts {
  width?: number;
  height?: number;
  label?: string;
  sublabel?: string;
  fill?: string;
  stroke?: string;
  dimTop?: string;
  dimRight?: string;
  dimLeft?: string;
  tooltip?: string;
  cols?: number;
  rows?: number;
}

export function drawMatrixBlock(
  g: Sel,
  x: number,
  y: number,
  opts: MatrixBlockOpts
): void {
  const {
    width = 80,
    height = 60,
    label = '',
    sublabel = '',
    fill = '#e3f2fd',
    stroke = '#1976d2',
    dimTop,
    dimRight,
    dimLeft,
    tooltip,
    cols = 8,
    rows = 6
  } = opts;

  const group = g.append('g').attr('transform', `translate(${x}, ${y})`);

  group
    .append('rect')
    .attr('width', width)
    .attr('height', height)
    .attr('rx', 4)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);

  const cellW = (width - 2) / cols;
  const cellH = (height - 2) / rows;
  // Seeded LCG for deterministic per-cell heatmap variation
  let seed = cols * 1000 + rows;
  const lcg = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const v = lcg();
      // Map to opacity range 0.04 – 0.22 for a realistic weight-like heatmap
      const opacity = 0.04 + v * 0.18;
      group
        .append('rect')
        .attr('x', 1 + c * cellW)
        .attr('y', 1 + r * cellH)
        .attr('width', cellW - 1)
        .attr('height', cellH - 1)
        .attr('fill', stroke)
        .attr('stroke', stroke)
        .attr('stroke-width', 0.15)
        .attr('opacity', opacity);
    }
  }

  if (label) {
    drawLabel(group as unknown as Sel, width / 2, height / 2 - 7, label, {
      size: 12,
      weight: '700',
      color: 'var(--text)'
    });
  }
  if (sublabel) {
    drawLabel(group as unknown as Sel, width / 2, height / 2 + 8, sublabel, {
      size: 9,
      font: 'monospace',
      color: 'var(--text-muted)'
    });
  }

  if (dimTop) {
    drawBrace(group as unknown as Sel, 0, -6, width, 'top', dimTop, 'var(--text-muted)');
  }
  if (dimRight) {
    drawBrace(group as unknown as Sel, width + 6, 0, height, 'right', dimRight, 'var(--text-muted)');
  }
  if (dimLeft) {
    drawBrace(group as unknown as Sel, -6, 0, height, 'left', dimLeft, 'var(--text-muted)');
  }

  if (tooltip) {
    const title = group.append('title');
    title.text(tooltip);
  }
}

export interface TensorGridOpts {
  rows: number;
  cols: number;
  cellW: number;
  cellH: number;
  maxDisplayRows?: number;
  maxDisplayCols?: number;
  fill?: string;
  stroke?: string;
  highlightRow?: number;
  highlightCol?: number;
  highlightColor?: string;
  cellColors?: (r: number, c: number) => string;
  label?: string;
  showEllipsis?: boolean;
}

export function drawTensorGrid(
  g: Sel,
  x: number,
  y: number,
  opts: TensorGridOpts
): { width: number; height: number } {
  const {
    rows,
    cols,
    cellW,
    cellH,
    maxDisplayRows = rows,
    maxDisplayCols = cols,
    fill = '#f8f9fa',
    stroke = '#dee2e6',
    highlightRow,
    highlightCol,
    highlightColor = '#bbdefb',
    cellColors,
    label,
    showEllipsis = true
  } = opts;

  const displayRows = Math.min(rows, maxDisplayRows);
  const displayCols = Math.min(cols, maxDisplayCols);
  const width = displayCols * cellW + (showEllipsis && cols > maxDisplayCols ? cellW : 0);
  const height = displayRows * cellH + (showEllipsis && rows > maxDisplayRows ? cellH : 0);

  const group = g.append('g').attr('transform', `translate(${x}, ${y})`);

  for (let r = 0; r < displayRows; r++) {
    for (let c = 0; c < displayCols; c++) {
      const isHighlighted = r === highlightRow || c === highlightCol;
      const cellFill = cellColors ? cellColors(r, c) : isHighlighted ? highlightColor : fill;
      group
        .append('rect')
        .attr('x', c * cellW)
        .attr('y', r * cellH)
        .attr('width', cellW)
        .attr('height', cellH)
        .attr('fill', cellFill)
        .attr('stroke', stroke)
        .attr('stroke-width', 0.3);
    }
  }

  if (showEllipsis && cols > maxDisplayCols) {
    drawLabel(group as unknown as Sel, width - cellW / 2, height / 2, '...', {
      size: 10,
      color: '#666'
    });
  }
  if (showEllipsis && rows > maxDisplayRows) {
    drawLabel(group as unknown as Sel, width / 2, height - cellH / 2, '...', {
      size: 10,
      color: '#666'
    });
  }

  if (label) {
    drawLabel(group as unknown as Sel, width / 2, -10, label, {
      size: 10,
      color: '#666'
    });
  }

  return { width, height };
}

export function drawBrace(
  g: Sel,
  x: number,
  y: number,
  length: number,
  direction: 'top' | 'bottom' | 'left' | 'right',
  label: string,
  color = '#999'
): void {
  const group = g.append('g').attr('transform', `translate(${x}, ${y})`);
  let path = '';
  let lx = 0;
  let ly = 0;
  let anchor: 'start' | 'middle' | 'end' = 'middle';

  if (direction === 'top') {
    path = `M0,10 Q0,0 ${length * 0.25},0 L${length * 0.75},0 Q${length},0 ${length},10`;
    lx = length / 2;
    ly = -6;
  } else if (direction === 'bottom') {
    path = `M0,0 Q0,10 ${length * 0.25},10 L${length * 0.75},10 Q${length},10 ${length},0`;
    lx = length / 2;
    ly = 18;
  } else if (direction === 'left') {
    path = `M10,0 Q0,0 0,${length * 0.25} L0,${length * 0.75} Q0,${length} 10,${length}`;
    lx = -6;
    ly = length / 2;
    anchor = 'end';
  } else if (direction === 'right') {
    path = `M0,0 Q10,0 10,${length * 0.25} L10,${length * 0.75} Q10,${length} 0,${length}`;
    lx = 16;
    ly = length / 2;
    anchor = 'start';
  }

  group
    .append('path')
    .attr('d', path)
    .attr('fill', 'none')
    .attr('stroke', color)
    .attr('stroke-width', 1);
  drawLabel(group as unknown as Sel, lx, ly, label, { size: 9, color, anchor });
}

export function drawDimBracket(
  g: Sel,
  x: number,
  y: number,
  length: number,
  direction: 'horizontal' | 'vertical',
  label: string,
  color = '#888'
): void {
  const group = g.append('g').attr('transform', `translate(${x}, ${y})`);
  if (direction === 'horizontal') {
    group
      .append('line')
      .attr('x1', 0)
      .attr('y1', 0)
      .attr('x2', length)
      .attr('y2', 0)
      .attr('stroke', color)
      .attr('stroke-width', 1);
    group
      .append('line')
      .attr('x1', 0)
      .attr('y1', -3)
      .attr('x2', 0)
      .attr('y2', 3)
      .attr('stroke', color)
      .attr('stroke-width', 1);
    group
      .append('line')
      .attr('x1', length)
      .attr('y1', -3)
      .attr('x2', length)
      .attr('y2', 3)
      .attr('stroke', color)
      .attr('stroke-width', 1);
    drawLabel(group as unknown as Sel, length / 2, -8, label, {
      size: 9,
      color,
      anchor: 'middle'
    });
  } else {
    group
      .append('line')
      .attr('x1', 0)
      .attr('y1', 0)
      .attr('x2', 0)
      .attr('y2', length)
      .attr('stroke', color)
      .attr('stroke-width', 1);
    group
      .append('line')
      .attr('x1', -3)
      .attr('y1', 0)
      .attr('x2', 3)
      .attr('y2', 0)
      .attr('stroke', color)
      .attr('stroke-width', 1);
    group
      .append('line')
      .attr('x1', -3)
      .attr('y1', length)
      .attr('x2', 3)
      .attr('y2', length)
      .attr('stroke', color)
      .attr('stroke-width', 1);
    drawLabel(group as unknown as Sel, 8, length / 2, label, {
      size: 9,
      color,
      anchor: 'start'
    });
  }
}

export interface StepBoxOpts {
  fill?: string;
  stroke?: string;
  formula?: string;
  step?: number;
}

export function drawStepBox(
  g: Sel,
  x: number,
  y: number,
  w: number,
  h: number,
  label: string,
  opts: StepBoxOpts = {}
): void {
  const { fill = '#e3f2fd', stroke = '#1976d2', formula, step } = opts;
  const group = g.append('g').attr('transform', `translate(${x}, ${y})`);

  group
    .append('rect')
    .attr('width', w)
    .attr('height', h)
    .attr('rx', 6)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);

  if (step !== undefined) {
    group
      .append('circle')
      .attr('cx', -10)
      .attr('cy', h / 2)
      .attr('r', 12)
      .attr('fill', stroke);
    drawLabel(group as unknown as Sel, -10, h / 2, String(step), {
      size: 11,
      weight: '700',
      color: '#fff'
    });
  }

  drawLabel(group as unknown as Sel, w / 2, h / 2 - (formula ? 7 : 0), label, {
    size: 12,
    weight: '600',
    color: '#333'
  });
  if (formula) {
    drawLabel(group as unknown as Sel, w / 2, h / 2 + 10, formula, {
      size: 9,
      font: 'monospace',
      color: '#666'
    });
  }
}

export function createStepGroup(g: Sel, stepNum: number): Sel {
  return g.append('g').attr('data-step', stepNum);
}

export interface ComponentLinkOpts {
  fill?: string;
  stroke?: string;
}

export function drawComponentLink(
  g: Sel,
  x: number,
  y: number,
  w: number,
  h: number,
  componentId: string,
  label: string,
  opts: ComponentLinkOpts = {}
): void {
  const { fill = '#e3f2fd', stroke = '#1976d2' } = opts;
  const group = g.append('g').attr('transform', `translate(${x}, ${y})`);
  group
    .append('rect')
    .attr('width', w)
    .attr('height', h)
    .attr('rx', 4)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5)
    .style('cursor', 'pointer');
  drawLabel(group as unknown as Sel, w / 2, h / 2, label, {
    size: 10,
    weight: '600',
    color: '#1565c0'
  });
  group.on('click', () => navigateTo(`#/component/${componentId}`));
}

export type ExplanationType = 'insight' | 'math' | 'perf' | 'warning';

export function drawExplanation(
  g: Sel,
  x: number,
  y: number,
  w: number,
  text: string,
  type: ExplanationType
): number {
  const colors: Record<ExplanationType, { fill: string; stroke: string; icon: string }> = {
    insight: { fill: '#e8f5e9', stroke: '#4caf50', icon: '💡' },
    math: { fill: '#e3f2fd', stroke: '#1976d2', icon: '∑' },
    perf: { fill: '#fff3e0', stroke: '#f57c00', icon: '⚡' },
    warning: { fill: '#ffebee', stroke: '#d32f2f', icon: '!' }
  };
  const { fill, stroke, icon } = colors[type];

  const padding = 12;
  const lineHeight = 16;
  const maxCharsPerLine = Math.max(20, Math.floor((w - padding * 2 - 28) / 6.5));
  const words = text.split(' ');
  const lines: string[] = [];
  let current = '';
  for (const word of words) {
    if ((current + ' ' + word).trim().length > maxCharsPerLine) {
      if (current) lines.push(current);
      current = word;
    } else {
      current = current ? `${current} ${word}` : word;
    }
  }
  if (current) lines.push(current);

  const h = Math.max(40, lines.length * lineHeight + padding * 2 + 4);
  const group = g.append('g').attr('transform', `translate(${x}, ${y})`);

  group
    .append('rect')
    .attr('width', w)
    .attr('height', h)
    .attr('rx', 6)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1);

  group
    .append('circle')
    .attr('cx', padding + 10)
    .attr('cy', h / 2)
    .attr('r', 10)
    .attr('fill', stroke);
  drawLabel(group as unknown as Sel, padding + 10, h / 2, icon, {
    size: 11,
    weight: '700',
    color: '#fff'
  });

  lines.forEach((line, i) => {
    drawLabel(group as unknown as Sel, padding + 26, padding + 12 + i * lineHeight, line, {
      size: 11,
      color: 'var(--text)',
      anchor: 'start'
    });
  });

  return y + h + 10;
}

export function drawCodeAnnotation(
  g: Sel,
  x: number,
  y: number,
  w: number,
  title: string,
  descLines: string[],
  codeLines: string[]
): number {
  const padding = 12;
  const lineHeight = 16;
  const codeLineHeight = 14;
  const descH = descLines.length * lineHeight + padding;
  const codeH = codeLines.length * codeLineHeight + padding;
  const h = descH + codeH + 20;

  const group = g.append('g').attr('transform', `translate(${x}, ${y})`);

  group
    .append('rect')
    .attr('width', w)
    .attr('height', h)
    .attr('rx', 6)
    .attr('fill', 'var(--surface)')
    .attr('stroke', 'var(--border)')
    .attr('stroke-width', 1);

  drawLabel(group as unknown as Sel, padding, padding + 6, title, {
    size: 12,
    weight: '700',
    color: 'var(--text)',
    anchor: 'start'
  });

  descLines.forEach((line, i) => {
    drawLabel(group as unknown as Sel, padding, padding + 22 + i * lineHeight, line, {
      size: 10,
      color: 'var(--text-muted)',
      anchor: 'start'
    });
  });

  const codeY = descH + 10;
  group
    .append('rect')
    .attr('x', padding)
    .attr('y', codeY)
    .attr('width', w - padding * 2)
    .attr('height', codeH)
    .attr('rx', 4)
    .attr('fill', 'var(--code-bg, #263238)')
    .attr('stroke', 'var(--border)');

  codeLines.forEach((line, i) => {
    drawLabel(group as unknown as Sel, padding + 8, codeY + 14 + i * codeLineHeight, line, {
      size: 9,
      font: 'monospace',
      color: 'var(--code-text, #aed581)',
      anchor: 'start'
    });
  });

  return y + h + 10;
}

export interface RotationArcOpts {
  color?: string;
  label?: string;
  showArrow?: boolean;
}

export function drawRotationArc(
  g: Sel,
  cx: number,
  cy: number,
  radius: number,
  startAngle: number,
  endAngle: number,
  opts: RotationArcOpts = {}
): void {
  const { color = '#e91e63', label, showArrow = true } = opts;

  const startX = cx + radius * Math.cos(startAngle);
  const startY = cy + radius * Math.sin(startAngle);
  const endX = cx + radius * Math.cos(endAngle);
  const endY = cy + radius * Math.sin(endAngle);
  const largeArc = endAngle - startAngle > Math.PI ? 1 : 0;

  const d = `M${startX},${startY} A${radius},${radius} 0 ${largeArc} 1 ${endX},${endY}`;
  g.append('path')
    .attr('d', d)
    .attr('fill', 'none')
    .attr('stroke', color)
    .attr('stroke-width', 1.5)
    .attr('marker-end', showArrow ? createArrowMarker(g, color) : '');

  if (label) {
    const midAngle = (startAngle + endAngle) / 2;
    const lx = cx + (radius + 14) * Math.cos(midAngle);
    const ly = cy + (radius + 14) * Math.sin(midAngle);
    drawLabel(g, lx, ly, label, { size: 10, color, weight: '600' });
  }
}

function createArrowMarker(g: Sel, color: string): string {
  const id = `arc-arrow-${Math.random().toString(36).slice(2, 9)}`;
  const defs = g.selectAll('defs').data([null]).join('defs');
  defs
    .append('marker')
    .attr('id', id)
    .attr('viewBox', '0 -5 10 10')
    .attr('refX', 8)
    .attr('refY', 0)
    .attr('markerWidth', 6)
    .attr('markerHeight', 6)
    .attr('orient', 'auto')
    .append('path')
    .attr('d', 'M0,-5L10,0L0,5')
    .attr('fill', color);
  return `url(#${id})`;
}

export function drawTensor(
  g: Sel,
  x: number,
  y: number,
  w: number,
  h: number,
  label: string,
  fill: string,
  stroke: string
): void {
  const group = g.append('g').attr('transform', `translate(${x}, ${y})`);
  group
    .append('rect')
    .attr('width', w)
    .attr('height', h)
    .attr('rx', 6)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);
  drawLabel(group as unknown as Sel, w / 2, h / 2, label, {
    size: 10,
    font: 'monospace',
    color: '#333'
  });
}

export function fmtNum(n: number): string {
  if (n >= 1e9) return (n / 1e9).toFixed(1) + 'B';
  if (n >= 1e6) return (n / 1e6).toFixed(1) + 'M';
  if (n >= 1e3) return (n / 1e3).toFixed(0) + 'K';
  return String(n);
}
